const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Search for PROD-3E35A7 in the raw binary and extract surrounding context
const str = data.toString('utf8');
const idx = str.indexOf('PROD-3E35A7');
if (idx >= 0) {
  // Print surrounding bytes as utf8
  const start = Math.max(0, idx - 500);
  const end = Math.min(str.length, idx + 500);
  const snippet = data.slice(start, end).toString('utf8');
  console.log('Context around PROD-3E35A7:');
  console.log(JSON.stringify(snippet));
}
"

