const db = require('better-sqlite3')('/workspace/world.db');

// Apply SAVE20OFF: $20 fixed discount
const result = db.prepare(\`
  UPDATE carts 
  SET applied_promo_codes_json = '[\"SAVE20OFF\"]',
      discount_amount = 20,
      total = subtotal - 20 + shipping_cost + gift_wrap_fee - loyalty_discount
  WHERE cart_id = 'CART-user_03dd1ad7'
\`).run();

console.log('Rows updated:', result.changes);

// Verify the updated cart
